"""Write web/model/start_state.json: the fixed start state, generated by the Python engine (engine/snake.py) with a fixed seed.
Run: .venv/bin/python scripts/make_start_state.py   (seed fixed below)
Classes: 0 empty, 1 food, 2-5 head (dir of travel U,D,L,R), 6-9 body, 10-13 tail (spikes/spike_a/common.py grid14).
"""
import json
import os
import sys

ROOT = os.path.join(os.path.dirname(__file__), "..")
sys.path.insert(0, ROOT)
sys.path.insert(0, os.path.join(ROOT, "spikes", "spike_a"))
from engine.snake import Snake  # noqa: E402
import common  # noqa: E402

SEED = 3


def main():
    s = Snake(seed=SEED)
    g = common.grid14(s.body, s.direction, s.food)
    out = {"n": 12, "seed": SEED, "grid": g.astype(int).tolist(), "head": list(s.body[0]), "food": list(s.food), "direction": "RIGHT",
           "generated_by": "scripts/make_start_state.py: Snake(seed=3) from engine/snake.py, grid via spikes/spike_a/common.py grid14",
           "command": "source scripts/env.sh && .venv/bin/python scripts/make_start_state.py"}
    json.dump(out, open(os.path.join(ROOT, "web", "model", "start_state.json"), "w"))
    print(json.dumps(out))


if __name__ == "__main__":
    main()
